import React, { useState, useEffect } from "react";
import { NavLink } from "react-router-dom";
import axios from "axios";
import { API_BASE_URL } from "../../config";

const navItems = [
  // ... (previous navItems)
];

export default function Sidebar({ open, onNavigate }) {
  const iconSrc = `${process.env.PUBLIC_URL}/asset/icon-logo.png`;
  const wordmarkSrc = `${process.env.PUBLIC_URL}/asset/font-logo.png`;

  const [room, setRoom] = useState({ name: "Memuat...", description: "..." });
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    // Clock interval
    const timer = setInterval(() => setTime(new Date()), 1000);

    // Fetch room data
    axios.get(`${API_BASE_URL}/rooms`)
      .then(res => setRoom(res.data))
      .catch(() => setRoom({ name: "Ruang Dosen", description: "Gedung 4 Sesi A & Dosen" }));

    return () => clearInterval(timer);
  }, []);

  const formattedTime = time.toLocaleTimeString("id-ID", {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false
  });

  const formattedDate = time.toLocaleDateString("id-ID", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric"
  });

  return (
    <aside className={open ? "sidebar sidebar--open" : "sidebar"}>
      <div className="sidebar__brand">
        <div className="sidebar__logo">
          <img className="sidebar__logoImg" src={iconSrc} alt="" />
        </div>
        <div className="sidebar__name">
          <img className="sidebar__wordmark" src={wordmarkSrc} alt="Hematrik" />
        </div>
      </div>

      <div className="sidebar__info">
        <div className="location-card">
          <div className="location-card__icon">
            <svg viewBox="0 0 24 24" width="20" height="20" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M12 21s-7-4.5-7-10a7 7 0 1 1 14 0c0 5.5-7 10-7 10z" stroke="#e91e63" strokeWidth="2" />
              <circle cx="12" cy="11" r="3" stroke="#e91e63" strokeWidth="2" />
            </svg>
          </div>
          <div className="location-card__content">
            <div className="location-card__label">Lokasi Monitoring</div>
            <div className="location-card__name">{room.name}</div>
            <div className="location-card__desc">{room.description}</div>
          </div>
        </div>

        <div className="clock-card">
          <div className="clock-card__time">{formattedTime}</div>
          <div className="clock-card__date">{formattedDate}</div>
        </div>
      </div>

      <nav className="nav" aria-label="Navigasi utama">
        {navItems.map((item) => (
          <NavLink
            key={item.to}
            to={item.to}
            end={item.to === "/"}
            className={({ isActive }) =>
              isActive ? "nav__link nav__item--active" : "nav__link"
            }
            onClick={() => onNavigate?.()}
          >
            <span className="nav__icon">{item.icon}</span>
            <span className="nav__label">{item.label}</span>
          </NavLink>
        ))}
      </nav>
    </aside>
  );
}
